function stateMatches(table,cols,expected){return {sql:`WITH expected AS(${expected}) SELECT (SELECT COUNT(*) FROM(SELECT ${cols} FROM ${table} EXCEPT SELECT ${cols} FROM expected))+(SELECT COUNT(*) FROM(SELECT ${cols} FROM expected EXCEPT SELECT ${cols} FROM ${table}))`,value:0};}
